<section class="ec-studio" x-show="studio && step === 2" x-cloak aria-labelledby="template-studio-heading">
    <header><div><span class="ec-note">{{ __('Template studio · Gemini') }}</span><h3 id="template-studio-heading">{{ __('Turn your idea into an email.') }}</h3></div><button type="button" @click="studio = false" :disabled="generating || studioBusy" class="am-button" aria-label="{{ __('Close template studio') }}"><i class="ph ph-x" aria-hidden="true"></i></button></header>
    <p class="ec-note">{{ __('Gemini follows existing TraKerja copy: friendly, conversational, and helpful. You review the facts and final wording.') }}</p>
    @if(!$geminiReady)<p class="ec-error" role="status">{{ __('Gemini is not configured. Ask the administrator to check the API key and model.') }}</p>@endif
    <fieldset :disabled="generating || studioBusy" class="ec-studio-brief">
        <div class="ec-field"><label for="template-prompt">{{ __('What would you like to say?') }}</label><textarea id="template-prompt" x-model="prompt" rows="4" maxlength="3000" placeholder="{{ __('Describe the audience, purpose, key facts, and action you want readers to take.') }}"></textarea></div>
        <div class="ec-generate-row"><label for="generation-language">{{ __('Draft language') }}<select id="generation-language" x-model="generationLanguage"><option value="id">Bahasa Indonesia</option><option value="en">English</option></select></label><button type="button" @click="generateDraft()" class="am-button am-button--primary" @if(!$geminiReady) disabled @endif><i class="ph ph-pencil-line" aria-hidden="true"></i><span x-text="generating ? @js(__('Writing your draft…')) : (draft ? @js(__('Generate again')) : @js(__('Generate draft')))"></span></button></div>
    </fieldset>
    <p class="ec-error" role="alert" x-show="studioError" x-text="studioError"></p>
    <p class="ec-note" role="status" x-show="generating">{{ __('This can take up to a minute. Your current draft stays available if generation fails.') }}</p>
    <template x-if="draft"><div class="ec-draft">
        <p class="ec-editor-note" x-show="draftNotes"><strong>{{ __('Editorial checks') }}</strong><span x-text="draftNotes"></span></p>
        <fieldset :disabled="generating || studioBusy"><div class="ec-field-pair"><div class="ec-field"><label for="draft-name">{{ __('Template name') }}</label><input id="draft-name" x-model="draft.name" maxlength="100"></div><div class="ec-field"><label for="draft-language">{{ __('Language') }}</label><select id="draft-language" x-model="draft.language"><option value="id">Bahasa Indonesia</option><option value="en">English</option></select></div></div><div class="ec-field"><label for="draft-subject">{{ __('Subject') }}</label><input id="draft-subject" x-model="draft.subject" maxlength="255"></div><div class="ec-field"><label for="draft-content">{{ __('Message body') }}</label><textarea id="draft-content" x-model="draft.content" rows="9" maxlength="5000"></textarea><p class="ec-note">{{ __('The recipient greeting, TraKerja signoff, and footer are added automatically.') }}</p></div><div class="ec-field-pair"><div class="ec-field"><label for="draft-cta">{{ __('Button text (optional)') }}</label><input id="draft-cta" x-model="draft.button_text" maxlength="100"></div><div class="ec-field"><label for="draft-url">{{ __('Button URL (optional)') }}</label><input id="draft-url" x-model="draft.button_url" type="url" maxlength="500" placeholder="https://"></div></div></fieldset>
        <button type="button" @click="previewDraft()" :disabled="generating || studioBusy" class="am-button"><i class="ph ph-eye" aria-hidden="true"></i>{{ __('Preview this draft') }}</button>
        <div x-show="reviewToken" class="ec-draft-preview"><iframe x-ref="draftFrame" title="{{ __('Template draft preview') }}" sandbox="" referrerpolicy="no-referrer"></iframe><label class="ec-review-check"><input type="checkbox" x-model="reviewed"><span>{{ __('I checked the facts, language, links, and final rendering of this template.') }}</span></label><button type="button" @click="saveDraft()" :disabled="!reviewed || !reviewToken || studioBusy || generating" class="am-button am-button--primary"><i class="ph ph-check-circle" aria-hidden="true"></i><span x-text="studioBusy ? @js(__('Saving…')) : @js(__('Verify & save template'))"></span></button></div>
    </div></template>
</section>
